+// Slop guard: shortcuts that make work look done without doing it. It reads only the run's own changes
+// (lines added and removed per file), so code that was already there is never flagged.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type SlopRule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+export type SlopFinding = { rule: SlopRule; path: string; line?: string };
+
+const TEST_FILE = /(^|\/)(tests?|__tests__|spec)\/|\.(test|spec)\.[cm]?[jt]sx?$|_test\.(go|py)$|(^|\/)test_[^/]*\.py$|_spec\.rb$/;
+const CODE_FILE = /\.([cm]?[jt]sx?|py|go|rs|java|kt|swift|rb|php|cs|c|cc|cpp|h|hpp|scala|dart|ex|exs|lua|sh)$/;
+const TS_FILE = /\.[cm]?tsx?$/;
+const ASSERTION = /\b(expect|assert\w*|should)\b|\bt\.(Error|Fatal|Fail)|\b(require|assert)\.\w+\(/;
