+  { rule: 'suppression', re: /@ts-(ignore|nocheck|expect-error)\b|eslint-disable|biome-ignore|#\s*type:\s*ignore|#\s*noqa\b|#\s*pylint:\s*disable|\/\/\s*nolint\b|#!?\[allow\(/ },
+  { rule: 'swallowed-error', re: /\bcatch\s*(\([^)]*\))?\s*\{\s*\}|\bexcept\b[^:]*:\s*(pass|\.\.\.)\s*$|\.catch\(\s*\(\s*\)\s*=>\s*(\{\s*\}|undefined|null)\s*\)/ },
+  { rule: 'type-escape', re: /\bas\s+any\b|<any>|\bas\s+unknown\s+as\b/, only: TS_FILE },
+  { rule: 'stub', re: /\b(throw|raise|panic)\b.*not\s*(yet\s*)?implemented|\bNotImplementedError\b|\b(todo|unimplemented)!\(/i },
+];
+
+const isCode = (path: string) => CODE_FILE.test(path);
+const isTest = (path: string) => TEST_FILE.test(path) && isCode(path);
+const count = (lines: string[], re: RegExp) => lines.filter((l) => re.test(l)).length;
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  for (const c of changes) {
+    if (!isCode(c.path)) continue;
+    if (c.deleted) {
+      if (isTest(c.path)) out.push({ rule: 'test-deleted', path: c.path });
