+export const slopReminder = (flags: string[]) =>
+  `Before this counts as done, look at these changes again. Each one can make work look finished without finishing it:\n${flags.map((f) => `- ${f}`).join('\n')}\nUndo the ones that are shortcuts and do the real fix. If one is right, keep it and say why in your report; anything left is listed on the receipt.`;
+
+// Reads `git diff -U0` output. Binary files carry no lines and are left out unless deleted.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  const unprefix = (p: string) => p.replace(/^[ab]\//, '');
+  for (const line of patch.split('\n')) {
+    if (line.startsWith('diff --git ')) {
+      const m = /^diff --git a\/(.*) b\/(.*)$/.exec(line);
+      cur = { path: m ? m[2]! : '', added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+    else if (inHunk) continue;
+    else if (line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (line.startsWith('+++ ') && line !== '+++ /dev/null') cur.path = unprefix(line.slice(4));
+    else if (line.startsWith('--- ') && line !== '--- /dev/null' && cur.deleted) cur.path = unprefix(line.slice(4));
+  }
+  return out.filter((c) => c.path);
+}
+
+// Without snapshots, the changes are what completed edit and write calls put in and took out.
+export function changesFromCalls(events: SessionEvent[], cwd: string): FileChange[] {
+  const intents = new Map<string, EventOf<'tool_intent'>>();
+  const out: FileChange[] = [];
+  const rel = (p: string) => (isAbsolute(p) ? relative(cwd, p) : p);
+  const lines = (s: unknown) => (typeof s === 'string' && s ? s.replace(/\n$/, '').split('\n') : []);
+  for (const e of events) {
+    if (e.kind === 'request') intents.clear();
+    if (e.kind === 'tool_intent') intents.set(e.callId, e);
+    if (e.kind !== 'tool_result' || e.status !== 'completed') continue;
+    const intent = intents.get(e.callId);
+    if (!intent || (intent.tool !== 'edit' && intent.tool !== 'write')) continue;
+    const path = rel(String(intent.input.path ?? ''));
+    if (intent.tool === 'write') out.push({ path, added: lines(intent.input.content), removed: [], deleted: false });
+    else {
+      const edits = Array.isArray(intent.input.edits) ? (intent.input.edits as Record<string, unknown>[]) : [];
+      out.push({ path, added: edits.flatMap((x) => lines(x.new_text)), removed: edits.flatMap((x) => lines(x.old_text)), deleted: false });
+    }
+  }
+  return out;
+}
