@@ -0,0 +1,38 @@
+import type { ToolOutput } from '../types.ts';
+import type { ToolSpec } from './registry.ts';
+
+// The writer's spawn tool. The model says what the work is; the client decides how it runs (model, tools,
+// policy). Explore only reads, so it runs in parallel with other reads; work may edit, so it runs alone between
+// two snapshots and the ledger records every file it changed. Only the child's report comes back.
+
+export type SpawnKind = 'explore' | 'work';
+export const SPAWN_KINDS: SpawnKind[] = ['explore', 'work'];
+
+export type SpawnRunner = (kind: SpawnKind, task: string, signal: AbortSignal) => Promise<ToolOutput>;
+
+export function spawnTool(runChild: SpawnRunner): ToolSpec {
+  return {
+    name: 'spawn',
+    description:
+      'Hand a self-contained piece of the task to a sub-thread: a fresh session that starts from your task text alone and returns only its final report. kind "explore" reads and searches without changing anything (several can run at once); kind "work" may edit files, and its changes still need a passing check from you. Write the task so it stands alone: what to find or do, where to look, and what the report should say.',
+    schema: {
+      type: 'object',
+      properties: {
+        kind: { type: 'string', enum: SPAWN_KINDS, description: 'explore: read-only; work: may edit files' },
+        task: { type: 'string', description: 'The sub-thread\'s whole task, written to stand alone' },
+      },
+      required: ['kind', 'task'],
+      additionalProperties: false,
+    },
+    effect: 'write_workspace',
+    effectOf: (input) => (input.kind === 'explore' ? 'read' : 'write_workspace'),
+    replay: 'unsafe',
+    async run(input, ctx) {
+      const kind = input.kind;
+      const task = typeof input.task === 'string' ? input.task.trim() : '';
+      if (kind !== 'explore' && kind !== 'work') return { text: `kind must be ${SPAWN_KINDS.join(' or ')}`, isError: true };
+      if (!task) return { text: 'task is empty', isError: true };
+      return runChild(kind, task, ctx.signal);
+    },
+  };
+}
