@@ -0,0 +1,31 @@
+import type { ModelSpec } from '../types.ts';
+import { latestBlock, type Thread } from './threads.ts';
+
+// A long session hands its thread to a new one before its context gets slow and dear: it writes a note while
+// its prefix is still cached, and the next session starts from the task and that note.
+
+export const HANDOFF_PROMPT = `Your context is getting long, so this session ends here and a new session of the same thread takes the task over. It sees the task and the note you write now, nothing else, though it can search this session's log with the recall tool. Do not call tools. Reply with the handoff note only:
+- what is done, with file paths, and what was checked (commands and results)
+- what is left, in order, and the next step
+- facts you found that are not obvious from the code, and dead ends you ruled out`;
+
+export const HANDOFF_NO_TOOLS = 'not run: this session is handing off. Reply with the handoff note only, without tools.';
+
+// Half the window, at most 150k, and below the point where the price per token goes up.
+export function defaultHandoffAt(model: ModelSpec): number {
+  const caps = [Math.floor(model.caps.contextWindow / 2), 150_000];
+  if (model.price.above) caps.push(Math.floor(model.price.above.tokens * 0.9));
+  return Math.min(...caps);
+}
+
+// The first user turn of a new session of a thread (after the environment preamble).
+export function threadNote(t: Thread, why: 'handoff' | 'resume'): string {
+  const intro =
+    why === 'handoff'
+      ? `This is thread ${t.id}. The previous session's context grew long, so it handed the task to you with the note below. The working tree already holds its changes; run the checks on them before you report done.`
+      : `This is thread ${t.id}. Earlier sessions worked on the task below; this is where the last one stopped.`;
+  const lines = [intro, 'Earlier sessions of this thread are searchable with the recall tool.'];
+  if (why === 'resume') lines.push(`<task>\n${t.task}\n</task>`);
+  if (t.latest) lines.push(latestBlock(t.latest));
+  return lines.join('\n');
+}
