--- a/src/core/project/threads.ts	1970-01-01 07:00:00
+++ b/src/core/project/threads.ts	2026-10-24 00:09:46
@@ -0,0 +1,147 @@
+import { appendFileSync, existsSync, mkdirSync, readdirSync, readFileSync } from 'node:fs';
+import { join } from 'node:path';
+
+// A thread is one task of a project, carried by one or more sessions (a handoff, a resume on another model, a
+// quota fallback). Its file is append-only JSONL at ~/.cedia/projects/<slug>/threads/<id>.jsonl; everything
+// about a thread is folded from those records, so nothing is ever edited.
+
+export type ThreadState = 'working' | 'done' | 'stopped';
+export type SessionWhy = 'start' | 'handoff' | 'resume' | 'fallback';
+
+export type ThreadRecord =
+  | { kind: 'open'; task: string }
+  | { kind: 'session'; sessionId: string; model: string; role: string; why: SessionWhy }
+  | { kind: 'handoff'; sessionId: string; note: string }
+  // from: another thread's id, or 'user'
+  | { kind: 'message'; id: string; from: string; text: string }
+  | { kind: 'delivered'; ids: string[]; sessionId: string }
+  | { kind: 'state'; state: ThreadState; result?: string; sessionId?: string };
+
+type Stamped = ThreadRecord & { at: string };
+export type ThreadMessage = { id: string; from: string; text: string; at: string };
+
+export type Thread = {
+  id: string;
+  title: string;
+  task: string;
+  state: ThreadState;
+  result?: string;
+  sessions: { sessionId: string; model: string; role: string; why: SessionWhy; at: string }[];
+  handoff?: { sessionId: string; note: string };
+  // Where a new session of the thread starts from: the later of the last handoff note and the last result.
+  latest?: { kind: 'handoff' | 'result'; sessionId: string; text: string };
+  messages: ThreadMessage[];
+  pending: ThreadMessage[]; // messages no session has been shown yet
+  updatedAt: string;
+};
+
+const ID = /^t-[0-9a-f]{8}$/;
+
+export const threadsDir = (home: string, slug: string) => join(home, 'projects', slug, 'threads');
+
+export function titleOf(task: string): string {
+  const line = task.trim().split('\n')[0]!.trim();
+  return line.length > 60 ? `${line.slice(0, 57)}...` : line;
+}
+
+export function foldThread(id: string, records: Stamped[]): Thread {
+  const t: Thread = { id, title: '', task: '', state: 'working', sessions: [], messages: [], pending: [], updatedAt: records.at(-1)?.at ?? '' };
+  const delivered = new Set<string>();
+  for (const r of records) {
+    switch (r.kind) {
+      case 'open':
+        t.task = r.task;
+        t.title = titleOf(r.task);
+        break;
+      case 'session':
+        t.sessions.push({ sessionId: r.sessionId, model: r.model, role: r.role, why: r.why, at: r.at });
+        break;
+      case 'handoff':
+        t.handoff = { sessionId: r.sessionId, note: r.note };
+        t.latest = { kind: 'handoff', sessionId: r.sessionId, text: r.note };
+        break;
+      case 'message':
+        t.messages.push({ id: r.id, from: r.from, text: r.text, at: r.at });
+        break;
+      case 'delivered':
+        for (const m of r.ids) delivered.add(m);
+        break;
+      case 'state':
+        t.state = r.state;
+        if (r.result !== undefined) {
+          t.result = r.result;
+          if (r.sessionId) t.latest = { kind: 'result', sessionId: r.sessionId, text: r.result };
+        }
+        break;
+    }
+  }
+  t.pending = t.messages.filter((m) => !delivered.has(m.id));
+  return t;
+}
+
+export class ThreadStore {
+  constructor(readonly dir: string) {}
+
+  private path(id: string): string {
+    if (!ID.test(id)) throw new Error(`${JSON.stringify(id)} is not a thread id`);
+    return join(this.dir, `${id}.jsonl`);
+  }
+
+  has(id: string): boolean {
+    return ID.test(id) && existsSync(this.path(id));
+  }
+
+  open(task: string): string {
+    mkdirSync(this.dir, { recursive: true });
+    let id: string;
+    do id = `t-${crypto.randomUUID().replace(/-/g, '').slice(0, 8)}`;
+    while (existsSync(this.path(id)));
+    appendFileSync(this.path(id), JSON.stringify({ kind: 'open', task, at: new Date().toISOString() }) + '\n');
+    return id;
+  }
+
+  append(id: string, record: ThreadRecord): void {
+    if (!this.has(id)) throw new Error(`no thread ${id}`);
+    appendFileSync(this.path(id), JSON.stringify({ ...record, at: new Date().toISOString() }) + '\n');
+  }
+
+  // Returns the message id; the message reaches the thread's session at its next turn boundary.
+  send(id: string, from: string, text: string): string {
+    const mid = `m-${crypto.randomUUID().replace(/-/g, '').slice(0, 12)}`;
+    this.append(id, { kind: 'message', id: mid, from, text });
+    return mid;
+  }
+
+  read(id: string): Thread {
+    const path = this.path(id);
+    if (!existsSync(path)) throw new Error(`no thread ${id}`);
+    const records = readFileSync(path, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l) as Stamped);
+    return foldThread(id, records);
+  }
+
+  // Most recently updated first.
+  list(): Thread[] {
+    if (!existsSync(this.dir)) return [];
+    return readdirSync(this.dir)
+      .filter((f) => ID.test(f.replace(/\.jsonl$/, '')) && f.endsWith('.jsonl'))
+      .map((f) => this.read(f.replace(/\.jsonl$/, '')))
+      .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
+  }
+}
+
+export const latestBlock = (l: NonNullable<Thread['latest']>) => `<${l.kind} session="${l.sessionId}">\n${l.text}\n</${l.kind}>`;
+
+export const messageBlock = (m: ThreadMessage) => `<message from="${m.from}" at="${m.at}">\n${m.text}\n</message>`;
+
+// The full view of a thread, for read_thread and `cedia threads show`. Messages only when asked.
+export function formatThread(t: Thread, opts: { messages?: boolean } = {}): string {
+  const lines = [`thread ${t.id}: ${t.title}`, `state: ${t.state}`, `<task>\n${t.task}\n</task>`];
+  if (t.handoff && t.latest?.kind !== 'handoff') lines.push(latestBlock({ kind: 'handoff', sessionId: t.handoff.sessionId, text: t.handoff.note }));
+  if (t.latest) lines.push(latestBlock(t.latest));
+  lines.push(`sessions: ${t.sessions.map((s) => `${s.sessionId} (${s.model}, ${s.why})`).join(', ') || 'none'}`);
+  if (opts.messages) {
+    const pending = new Set(t.pending.map((m) => m.id));
+    for (const m of t.messages) lines.push(`${messageBlock(m)}${pending.has(m.id) ? ' (not seen yet)' : ''}`);
+  }
+  return lines.join('\n');
+}
