+import { formatThread, type ThreadStore } from '../project/threads.ts';
+import type { SessionEvent } from '../types.ts';
+import { clip, type ToolSpec } from './registry.ts';
+
+export type RecallSource = { id: string; events: () => SessionEvent[] };
+
+const MAX_MATCHES = 40;
+const SNIPPET = 300;
+
+// The line around a match, cut to a readable length.
+function snippet(text: string, index: number): string {
+  const start = text.lastIndexOf('\n', index) + 1;
+  const endAt = text.indexOf('\n', index);
+  const line = text.slice(start, endAt < 0 ? undefined : endAt).trim();
+  return line.length > SNIPPET ? `${line.slice(0, SNIPPET)}...` : line;
+}
+
+// Searches the logs of the thread's earlier sessions: what was said, called and returned.
+export function recallTool(sources: () => RecallSource[]): ToolSpec {
+  return {
+    name: 'recall',
+    description:
+      "Search the logs of this thread's earlier sessions (messages, tool calls and tool results) for a regular expression, case-insensitive. Returns matching lines with the session and the event they came from.",
+    schema: {
+      type: 'object',
+      properties: { query: { type: 'string', description: 'Regular expression, or plain text' } },
+      required: ['query'],
+      additionalProperties: false,
+    },
+    effect: 'read',
+    replay: 'safe',
+    async run(input) {
+      const query = String(input.query ?? '');
+      if (!query) return { text: 'query is required', isError: true };
+      let re: RegExp;
+      try {
+        re = new RegExp(query, 'i');
+      } catch {
+        re = new RegExp(query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
+      }
+      const all = sources();
+      const hits: string[] = [];
+      let total = 0;
+      all.forEach((s, i) => {
+        const names = new Map<string, string>();
+        const where = `session ${i + 1} of ${all.length}`;
+        const look = (label: string, text: string) => {
+          const m = re.exec(text);
+          if (!m) return;
+          total++;
+          if (hits.length < MAX_MATCHES) hits.push(`[${where} · ${label}] ${snippet(text, m.index)}`);
+        };
+        for (const e of s.events()) {
+          if (e.kind === 'user') look('user', e.text);
+          else if (e.kind === 'assistant')
+            for (const b of e.blocks) {
+              if (b.type === 'text') look('assistant', b.text);
+              else if (b.type === 'tool_use') {
+                names.set(b.callId ?? b.id, b.name);
+                look(`call ${b.name}`, JSON.stringify(b.input));
+              }
+            }
+          else if (e.kind === 'tool_result') look(`result ${names.get(e.callId) ?? 'tool'}`, e.output.text);
+        }
+      });
+      if (!total) return { text: `no match for ${JSON.stringify(query)} in ${all.length} earlier session${all.length === 1 ? '' : 's'}`, isError: false };
+      const more = total > hits.length ? `\n[${total - hits.length} more; narrow the query]` : '';
+      return { text: clip(`${total} match${total === 1 ? '' : 'es'}\n${hits.join('\n')}${more}`), isError: false };
+    },
+  };
+}
+
+// threads, read_thread and message_thread: see the project's other threads and message them. A thread never
+// lists or messages itself.
+export function threadTools(store: ThreadStore, me: string): ToolSpec[] {
+  const other = (input: Record<string, unknown>): string | { error: string } => {
+    const id = String(input.id ?? '');
+    if (id === me) return { error: 'that is this thread' };
+    if (!store.has(id)) return { error: `no thread ${id} in this project` };
+    return id;
+  };
+  const idSchema = { type: 'string', description: 'Thread id, e.g. t-1a2b3c4d' };
+  return [
+    {
+      name: 'threads',
+      description: "List this project's other threads: id, state, title and where each one stands.",
+      schema: { type: 'object', properties: {}, additionalProperties: false },
+      effect: 'read',
+      replay: 'safe',
+      async run() {
+        const rows = store.list().filter((t) => t.id !== me);
+        if (!rows.length) return { text: 'no other threads in this project', isError: false };
+        const line = (s: string) => (s.length > 200 ? `${s.slice(0, 200)}...` : s).replace(/\s+/g, ' ');
+        return {
+          text: clip(rows.map((t) => `${t.id} [${t.state}] ${t.title}${t.latest ? `\n  ${t.latest.kind}: ${line(t.latest.text)}` : ''}`).join('\n')),
+          isError: false,
+        };
+      },
+    },
+    {
+      name: 'read_thread',
+      description: "Read another thread of this project: its task, its latest handoff note or result, and its sessions.",
+      schema: { type: 'object', properties: { id: idSchema }, required: ['id'], additionalProperties: false },
+      effect: 'read',
+      replay: 'safe',
+      async run(input) {
+        const id = other(input);
+        if (typeof id !== 'string') return { text: id.error, isError: true };
+        return { text: clip(formatThread(store.read(id))), isError: false };
+      },
+    },
+    {
+      name: 'message_thread',
+      description: 'Send a message to another thread of this project. Its session sees it at its next turn, or when it resumes.',
+      schema: {
+        type: 'object',
+        properties: { id: idSchema, text: { type: 'string', description: 'The message' } },
+        required: ['id', 'text'],
+        additionalProperties: false,
+      },
+      // It changes state outside this session, so a read-only session may not send.
+      effect: 'write_workspace',
+      replay: 'unsafe',
+      async run(input) {
+        const id = other(input);
+        if (typeof id !== 'string') return { text: id.error, isError: true };
+        const text = String(input.text ?? '').trim();
+        if (!text) return { text: 'text is required', isError: true };
+        store.send(id, me, text);
+        return { text: `sent to ${id}`, isError: false };
+      },
+    },
+  ];
+}
